impl Guest for Component { fn describe()->ToolManifest{ToolManifest{name:"moo-invoke-verb".into(),description:"Invoke a MOO verb through Torchship's web-host API. This may mutate world state.".into(),args_schema_json:json!({"type":"object","properties":{"object":{"type":"string"},"verb":{"type":"string"},"args":{"type":"array","default":[]},"wizard":{"type":"boolean","default":false},"timeout_ms":{"type":"integer","minimum":0,"maximum":300000}},"required":["object","verb"],"additionalProperties":false}).to_string(),capabilities:vec!["group:moo".into(),"http".into()]}} fn invoke(_:String,args_json:String,config_json:String)->Result<String,String>{let a:Value=serde_json::from_str(&args_json).map_err(|e|e.to_string())?;let object=a.get("object").and_then(Value::as_str).ok_or("missing object")?;let verb=a.get("verb").and_then(Value::as_str).ok_or("missing verb")?;let args=a.get("args").cloned().unwrap_or_else(||json!([]));if !args.is_array(){return Err("args must be an array".into())}let wizard=a.get("wizard").and_then(Value::as_bool).unwrap_or(false);let ms=a.get("timeout_ms").and_then(Value::as_u64).unwrap_or(0);if ms>300000{return Err("timeout_ms exceeds 300000".into())}let mut path=format!("/v1/verbs/{}/{}/invoke",object_path_segment(object)?,path_segment(verb));if ms>0{path.push_str(&format!("?timeout_ms={ms}"));}let resp=Moo::from_config(&config_json)?.authenticated("POST",&path,Some("application/json"),Some(&json!({"args":args}).to_string()),wizard)?;let r=moo::decode_captured(&resp,&path)?;Ok(bounded(&json!({"success":r.success,"value":r.value,"error":r.error,"output":r.output,"timed_out":r.timed_out,"cancelled":r.cancelled}).to_string(),32000))} }
